    $("bumpChk").checked=bumpOn;$("bump").classList.toggle("on",bumpOn);$("bumpLine").hidden=!bumpOn;$("bumpLineT").textContent=BUMP.line;$("bumpLineV").textContent=money(BUMP.price);
