      let h="";for(let i=1;i<=slots;i++){const fr=i%4===0,f=i<=T,got=fr&&(i/4<=x.apps||T>=i-1);h+=`<i class="${f?"f ":""}${fr?"fr ":""}${got?"got":""}">${fr?"FREE":""}</i>`}
