{const h=new URLSearchParams(location.search).get("hero");if(h&&PRODUCTS.some(p=>p.id===h)){Hero.jumpTo(h);history.replaceState(null,"",location.pathname+location.hash)}}
$("arcPrev").onclick=()=>Hero.step(-1);$("arcNext").onclick=()=>Hero.step(1);
/* desktop rail arrows: scroll by a page of cards */
document.querySelectorAll("#hRail,#hHatRail,#hPmnRail,#pAlso,#hSamoaRail,#hTongaRail").forEach(r=>{const w=document.createElement("div");w.className="rail-wrap"+(r.classList.contains("big-rail")?" big-wrap":"");r.parentNode.insertBefore(w,r);w.append(r);
  const mk=(cls,d,label,path)=>{const b=document.createElement("button");b.type="button";b.className="rail-btn "+cls;b.setAttribute("aria-label",label);b.innerHTML=`<svg viewBox="0 0 24 24"><path d="${path}"/></svg>`;b.onclick=()=>r.scrollBy({left:d*r.clientWidth*0.9,behavior:reduceMotion?"auto":"smooth"});w.append(b);return b};
  const p=mk("prev",-1,"Scroll left","M15 5l-7 7 7 7"),n=mk("next",1,"Scroll right","M9 5l7 7-7 7");
  const sync=()=>{p.disabled=r.scrollLeft<4;n.disabled=r.scrollLeft+r.clientWidth>=r.scrollWidth-4};
  r.addEventListener("scroll",sync,{passive:true});addEventListener("resize",sync);setTimeout(sync,300)});
